NAME = "surge"

def objective(f, state, region_mask, chosen, graph, prob):
    P0, P1 = prob(f.a), prob(f.a + 1)
    D = np.where(f.eligible, P1 - P0, 0.0)
    w = P1 * (P1 - P0) + 1e-3 * f.eligible   # receivers near flipping are worth the push
    return D @ graph.adjT + w @ graph.adjT + f.eligible * (1.0 - P0)
